package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; import java.util.*; import vn.edu.hcmute.bookstore_24110202.dto.*; import vn.edu.hcmute.bookstore_24110202.service.impl.*; import vn.edu.hcmute.bookstore_24110202.util.*;
@WebServlet("/admin/authors") public class AdminAuthorController_24110202 extends HttpServlet {private final AuthorServiceImpl_24110202 service=new AuthorServiceImpl_24110202();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String path=q.getPathInfo();if(path==null||path.equals("/")){int page=Math.max(1,Optional.ofNullable(ValidationUtil_24110202.integer(q.getParameter("page"))).orElse(1));int total=ValidationUtil_24110202.totalPages(service.count(),10);q.setAttribute("authors",service.page(Math.min(page,total),10));q.setAttribute("currentPage",Math.min(page,total));q.setAttribute("totalPages",total);q.getRequestDispatcher("/WEB-INF/views/admin/author-list.jsp").include(q,p);return;}Integer id=ValidationUtil_24110202.integer(q.getParameter("id"));if(id!=null)q.setAttribute("author",service.find(id).orElse(null));q.getRequestDispatcher("/WEB-INF/views/admin/author-form.jsp").include(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{String action=q.getParameter("action");Integer id=ValidationUtil_24110202.integer(q.getParameter("id"));if("delete".equals(action)){if(id!=null&&service.delete(id))q.getSession().setAttribute("flashSuccess","Đã xóa tác giả");else q.getSession().setAttribute("flashError","Không thể xóa tác giả đang được dùng bởi sách");}else{AuthorForm_24110202 f=new AuthorForm_24110202();f.setName(q.getParameter("name"));f.setDateOfBirth(q.getParameter("dateOfBirth"));if(f.getName()==null||f.getName().isBlank()||f.getName().length()>100||!ValidationUtil_24110202.pastOrToday(f.getDateOfBirth())){q.setAttribute("errors",Map.of("name","Tên tác giả hoặc ngày sinh không hợp lệ"));q.getRequestDispatcher("/WEB-INF/views/admin/author-form.jsp").include(q,p);return;}service.save(f,"edit".equals(action)?id:null);q.getSession().setAttribute("flashSuccess","Đã lưu tác giả");}p.sendRedirect(q.getContextPath()+"/admin/authors");}}
